    /// <summary>sheets/tuning.json, one field per row.</summary>
    public static class Tune
    {
        /// <summary>Megabonk has no sprint: always at full speed while moving (RoR2 still stops sprint when moving backwards or during some skills). The Sprint key becomes Slide. (bool (1/0))</summary>
        public static float AutoSprint = 1.0f;
        /// <summary>Top running speed from input (maxRunSpeed 10 x MoveSpeedMultiplier). Risk of Rain 2 speed items scale it. Measured from Megabonk (GameAssembly: PlayerMovement / PlayerMovementValues, 50 Hz physics). (m/s)</summary>
        public static float RunSpeed = 10.0f;
        /// <summary>Acceleration from input on the ground (moveSpeed force 2700 x fixed step 0.02). Input along a direction stops pushing once you already go faster than run_speed that way. Measured from Megabonk (GameAssembly: PlayerMovement / PlayerMovementValues, 50 Hz physics). (m/s per s)</summary>
        public static float RunAccel = 54.0f;
        /// <summary>Counter-movement on the ground: speed in a direction you are not pushing fades at this rate (counterMovement 0.25 x 54). Measured from Megabonk (GameAssembly: PlayerMovement / PlayerMovementValues, 50 Hz physics). (per s)</summary>
        public static float GroundFriction = 13.5f;
        /// <summary>On the ground, speed above run_speed fades at this rate while you keep moving (slowDownSpeed 0.01 x 54): momentum lasts. Measured from Megabonk (GameAssembly: PlayerMovement / PlayerMovementValues, 50 Hz physics). (per s)</summary>
        public static float OverspeedDecayHold = 0.54f;
        /// <summary>Same, when you let go of the movement keys (slowDownSpeed 0.1 x 54). Measured from Megabonk (GameAssembly: PlayerMovement / PlayerMovementValues, 50 Hz physics). (per s)</summary>
        public static float OverspeedDecayRelease = 5.4f;
        /// <summary>After landing, no counter-movement or speed fade for this long (justLandedCounter 15 ticks), so a quick jump keeps all your speed (bunny hop). Measured from Megabonk (GameAssembly: PlayerMovement / PlayerMovementValues, 50 Hz physics). (s)</summary>
        public static float LandGrace = 0.3f;
        /// <summary>Steering in the air (0.45 x run_accel). Like on the ground it cannot push you past run_speed, and never slows you (air_drag does that, slowly). Measured from Megabonk (GameAssembly: PlayerMovement / PlayerMovementValues, 50 Hz physics). (m/s per s)</summary>
        public static float AirAccel = 24.3f;
        /// <summary>In the air, speed you are not steering along (all of it with no input) fades at this rate: Megabonk's MovementTick pushes against the look-relative velocity on each axis without input by airDeceleration 0.003 x moveSpeed 2700 x 0.02 (about 16% per second). (per s)</summary>
        public static float AirDrag = 0.162f;
        /// <summary>Jump launch speed (JumpHeight stat 7 x mass as an impulse). Jumping while still rising halves the old upward speed first. Measured from Megabonk (GameAssembly: PlayerMovement / PlayerMovementValues, 50 Hz physics). (m/s)</summary>
        public static float JumpSpeed = 7.0f;
        /// <summary>Megabonk's gravity (Physics gravity -19.62); Risk of Rain 2 uses 30, so players fall slower and jumps hang longer. Measured from Megabonk (GameAssembly: PlayerMovement / PlayerMovementValues, 50 Hz physics). (m/s per s)</summary>
        public static float Gravity = 19.62f;
        /// <summary>Speed added when a slide starts (slideForce 200 x 0.02), only if you went faster than slide_boost_min_speed since the last slide. Measured from Megabonk (GameAssembly: PlayerMovement / PlayerMovementValues, 50 Hz physics). (m/s)</summary>
        public static float SlideBoost = 4.0f;
        /// <summary>slideThresholdSpeed: the next slide boost is ready once you reach this speed. Measured from Megabonk (GameAssembly: PlayerMovement / PlayerMovementValues, 50 Hz physics). (m/s)</summary>
        public static float SlideBoostMinSpeed = 8.0f;
        /// <summary>Time before another slide can boost (slideCooldownCounterMax 25 ticks). Measured from Megabonk (GameAssembly: PlayerMovement / PlayerMovementValues, 50 Hz physics). (s)</summary>
        public static float SlideCooldown = 0.5f;
        /// <summary>Speed lost per second while sliding (slideCounterMovement 0.1 x 54), the same at any speed. Measured from Megabonk (GameAssembly: PlayerMovement / PlayerMovementValues, 50 Hz physics). (m/s per s)</summary>
        public static float SlideFriction = 5.4f;
        /// <summary>Sliding downhill speeds you up by gravity along the slope (Megabonk's rigidbody has no friction while sliding); uphill slows you. Measured from Megabonk (GameAssembly: PlayerMovement / PlayerMovementValues, 50 Hz physics). (x gravity along slope)</summary>
        public static float SlideSlopeGain = 1.0f;
        /// <summary>Sideways steering while sliding (forward input does nothing in a slide; sideways input pushes at run_accel). Measured from Megabonk (GameAssembly: PlayerMovement / PlayerMovementValues, 50 Hz physics). (m/s per s)</summary>
        public static float SlideSteer = 54.0f;
        /// <summary>Holding Slide below slide_boost_min_speed crouches instead of sliding, and a slide that slows down to this becomes a crouch; crouching caps your speed at this x run speed (Megabonk's CheckInput: GetMaxSpeed x 0.5 while crouched). (x run speed)</summary>
        public static float CrouchSpeed = 0.5f;
        /// <summary>Climbing speed up a wall: max(this, 1.5 x run speed) (minWallClimbSpeed 10). Megabonk's PlayerMovement.WallClimbing / CanWallClimb (GameAssembly), Monke's WallClimb passive only. (m/s)</summary>
        public static float WallclimbMinSpeed = 10.0f;
        /// <summary>Speed pressing you into the wall while climbing. Megabonk's PlayerMovement.WallClimbing / CanWallClimb (GameAssembly), Monke's WallClimb passive only. (m/s)</summary>
        public static float WallclimbPush = 4.0f;
        /// <summary>After a climb ends, the next one waits this long (wallClimbCooldown). Megabonk's PlayerMovement.WallClimbing / CanWallClimb (GameAssembly), Monke's WallClimb passive only. (s)</summary>
        public static float WallclimbCooldown = 0.4f;
        /// <summary>You climb when your movement points at the wall within this angle (wallrunAttachAngle). Megabonk's PlayerMovement.WallClimbing / CanWallClimb (GameAssembly), Monke's WallClimb passive only. (degrees)</summary>
        public static float WallclimbAngle = 60.0f;
        /// <summary>Safety cap on horizontal speed (Megabonk has none; this only stops runaway physics). Measured from Megabonk (GameAssembly: PlayerMovement / PlayerMovementValues, 50 Hz physics). (m/s)</summary>
        public static float MaxSpeed = 40.0f;
        /// <summary>Monster spawn budget over time (stage and Teleporter directors without a boss squad). (x director credit)</summary>
        public static float HordeCredit = 1.8f;
        /// <summary>Most monsters one director wave may spawn (RoR2 default 6). Cheap monsters are no longer skipped. (monsters)</summary>
        public static float HordeWaveSize = 14.0f;
        /// <summary>Time between director waves. (x reroll interval)</summary>
        public static float HordeInterval = 0.6f;
        /// <summary>Non-boss monsters are weaker so the horde mows down like in Megabonk. (x max health)</summary>
        public static float HordeHealth = 0.6f;
        /// <summary>Extra monster credit for the Teleporter's horde director when the Megabonk boss event starts. (director credit (x difficulty))</summary>
        public static float BossSwarmCredit = 400.0f;
        /// <summary>Monster team soft limit (RoR2 default 40). (monsters)</summary>
        public static float HordeLimit = 70.0f;
        /// <summary>Invincibility while the level-up menu is open; ends early when you pick. The countdown turns red and shakes in its last 30%. (s)</summary>
        public static float UpgradeInvincibility = 10.0f;
        /// <summary>Chance that a level-up card is a Megabonk weapon (Megabonk survivors only), otherwise a tome. (0-1 per card)</summary>
        public static float WeaponOfferChance = 0.45f;
        /// <summary>A chest opened by a Megabonk survivor holds a Megabonk upgrade (a bonus pick: the level-up menu with weapons and tomes) instead of its item this often (src/Chests.cs). Item chests only. (chance per chest)</summary>
        public static float ChestUpgradeChance = 0.5f;
        /// <summary>XP in each gem compared with Risk of Rain 2's own kill XP (Megabonk levels up more often). (x RoR2 kill XP)</summary>
        public static float XpMultiplier = 1.5f;
        /// <summary>XP gems within this distance of a player fly to them and are collected. (m)</summary>
        public static float XpPickupRadius = 7.0f;
        /// <summary>Most gems on the ground; past this the oldest gem is collected for the team at once. (gems)</summary>
        public static float XpGemLimit = 300.0f;
        /// <summary>Megabonk Charge Shrines placed on each normal stage (with a Teleporter), next to Risk of Rain 2's own shrines. (count)</summary>
        public static float ChargeShrinesPerStage = 4.0f;
        /// <summary>Time a player must stand inside a Charge Shrine to charge it fully. Leaving pauses the charge (it slowly drains). (s)</summary>
        public static float ChargeShrineSeconds = 5.0f;
        /// <summary>Radius of a Charge Shrine's circle. (m)</summary>
        public static float ChargeShrineRadius = 5.0f;
        /// <summary>Upgrade picks every player gets when a Charge Shrine is fully charged. (picks)</summary>
        public static float ChargeShrinePicks = 1.0f;
        /// <summary>Megabonk Magnet Shrines per stage: stand in one briefly and every XP gem on the map flies to you. (count)</summary>
        public static float MagnetShrinesPerStage = 1.0f;
        /// <summary>Time to stand in a Magnet Shrine to use it. (s)</summary>
        public static float MagnetShrineSeconds = 1.0f;
        /// <summary>Time to stand in a Moai, Greed or Challenge Shrine to use it. (s)</summary>
        public static float ShrineUseSeconds = 1.5f;
        /// <summary>Megabonk Moai Shrines per stage: every player gets a random tome at a rolled rarity (luck helps). (count)</summary>
        public static float MoaiShrinesPerStage = 1.0f;
        /// <summary>Megabonk Greed Shrines per stage: more gold and more monsters for the rest of the stage. (count)</summary>
        public static float GreedShrinesPerStage = 1.0f;
        /// <summary>Greed Shrine: gold from monsters spawned afterwards is multiplied by this (stacks per shrine). (x)</summary>
        public static float GreedGold = 1.5f;
        /// <summary>Greed Shrine: the stage's monster directors earn this much more credit (stacks per shrine). (x)</summary>
        public static float GreedMonsters = 1.5f;
        /// <summary>Megabonk Challenge Shrines per stage: a champion wave; kill it and every player gets an upgrade pick. (count)</summary>
        public static float ChallengeShrinesPerStage = 1.0f;
        /// <summary>Challenge Shrine budget, times the run's difficulty coefficient: a champion from the stage's monsters that fits (elite when it can), else the usual Shrine of Combat pick (which uses 100). (credits)</summary>
        public static float ChallengeCredit = 400.0f;
        /// <summary>Megabonk Cursed Shrines per stage (our reading of Megabonk's curse: risk for reward). (count)</summary>
        public static float CursedShrinesPerStage = 1.0f;
        /// <summary>Upgrade picks every player gets from a Cursed Shrine. (picks)</summary>
        public static float CursedShrinePicks = 2.0f;
        /// <summary>Cursed Shrine: the stage's monster directors earn this much more credit, and elites cost half as much, for the rest of the stage. (x)</summary>
        public static float CursedMonsters = 1.3f;
        /// <summary>Monster credit per second for the Megabonk swarm during a final boss fight (Mithrix/Ghost King, False Son/Shadow King, Voidling), times the square root of the difficulty coefficient. (credits/s)</summary>
        public static float FinalSwarmCredit = 12.0f;
        /// <summary>Colour saturation added on stages (Megabonk's bright colours). (-100..100)</summary>
        public static float LookSaturation = 35.0f;
        /// <summary>Contrast added on stages. (-100..100)</summary>
        public static float LookContrast = 15.0f;
        /// <summary>Brightness added on stages (HDR grading, which the stages checked use: lakes, foggyswamp, sulfurpools, dampcavesimple). (EV)</summary>
        public static float LookExposure = 0.35f;
        /// <summary>Brightness added on stages that grade in LDR (none of the stages checked so far). (-100..100)</summary>
        public static float LookBrightness = 12.0f;
        /// <summary>Stage fog strength is multiplied by this. 1 = unchanged: lighter fog made Risk of Rain 2's stages darker (their fog carries much of the light). (x)</summary>
        public static float LookFog = 1.0f;
        /// <summary>Above this ground speed the run clip plays instead of idle. Ours: Megabonk's Animator transitions are not read. (m/s)</summary>
        public static float AnimRunSpeed = 1.0f;
        /// <summary>In the air, rising faster than this plays the jump clip, otherwise the falling clip. Ours: Megabonk's Animator transitions are not read. (m/s)</summary>
        public static float AnimFallSpeed = 0.5f;
        /// <summary>Crossfade time between clips. Ours: Megabonk's Animator transitions are not read. (s)</summary>
        public static float AnimBlend = 0.15f;
        /// <summary>A clip change has to be wanted this long before it happens (jumps start at once), so walking at the edge of run speed does not flicker. Ours: Megabonk's Animator transitions are not read. (s)</summary>
        public static float AnimHold = 0.12f;
        /// <summary>Volume of Megabonk's sounds, on top of Risk of Rain 2's master and sound effect volume. (x)</summary>
        public static float SoundVolume = 0.8f;
        /// <summary>Megabonk's music (MegabonkMusic) plays at the game's master x music volume times this. (x music volume)</summary>
        public static float MusicVolume = 0.7f;
        /// <summary>Megabonk weapon damage (mbDamage in weapons.json, e.g. Revolver 5 per bullet, Sniper 22) times this is the hit's damage coefficient in Risk of Rain 2 (x the body's base damage). Keeps Megabonk's balance between weapons; this value sets the overall strength. (x base damage per Megabonk damage point)</summary>
        public static float WeaponDamageScale = 0.4f;
        /// <summary>What a Risk of Rain 2 survivor's own kit deals per second, in units of its base damage, counting each extra enemy a hit reaches (Commando: Double Tap about 5/s, Phase Round and Suppressive Fire about 1.7/s more, little area). A Megabonk survivor's weapons are scaled towards this so they are as strong as the Risk of Rain 2 survivors next to them; RoR2 items, levels and tomes then grow both alike. (damage per second (x base damage))</summary>
        public static float BalanceReferencePower = 5.0f;
        /// <summary>Each weapon level a Megabonk survivor gains (a new weapon is one level, an upgrade pick adds its rarity's levels) raises the power its weapons may reach by this much of the reference: a little less than one Damage Tome point (8%), since a Megabonk survivor's weapons also reach more enemies, so a weapon pick and a tome pick are worth the same and Risk of Rain 2 survivors (who take only tomes) keep up. (x reference power per weapon level)</summary>
        public static float BalancePickValue = 0.05f;
        /// <summary>How strongly the weapons are pulled to the allowed power: 1 makes every loadout exactly as strong, lower lets strong weapon choices stay a little stronger (power = allowed^strength x raw^(1-strength)). (0..1)</summary>
        public static float BalanceStrength = 0.6f;
        /// <summary>Weak loadouts are raised at most this much (most are lowered). (x)</summary>
        public static float BalanceMaxBoost = 1.15f;
        /// <summary>Enemies a melee swing hits on average in a horde (used to compare its power). (enemies)</summary>
        public static float BalanceAreaMelee = 2.0f;
        /// <summary>Enemies an aura hits on average in a horde. (enemies)</summary>
        public static float BalanceAreaAura = 2.0f;
        /// <summary>Enemies a projectile hits on average (some explode, bounce or return). (enemies)</summary>
        public static float BalanceAreaProjectile = 1.3f;
        /// <summary>Enemies a lightning strike reaches on average (it chains). (enemies)</summary>
        public static float BalanceAreaLightning = 2.0f;
        /// <summary>Enemies a piercing bullet hits on average (Sniper, Space Noodle); other bullets hit one. (enemies)</summary>
        public static float BalanceAreaPierce = 2.0f;
        /// <summary>Megabonk's StageSummoner.GetNumTargetEnemies: the enemies it keeps alive start at 5 + 200 x (stage time / stageDuration), times (1 + 0.4 x stage) here (Megabonk: 1 + 0.7 x Difficulty + 0.4 x its stage multiplier). This is the 5. (monsters)</summary>
        public static float HordeTargetStart = 5.0f;
        /// <summary>Megabonk's +200 enemies over a stage (GetNumTargetEnemies). (monsters)</summary>
        public static float HordeTargetRamp = 200.0f;
        /// <summary>Megabonk's stageDuration (MapData, Forest: 600 s): the target ramps over this long. (s)</summary>
        public static float HordeStageSeconds = 600.0f;
        /// <summary>Each stage cleared raises the target by this much of itself (Megabonk's 0.4 x stage multiplier). (x per stage)</summary>
        public static float HordeTargetStageGrowth = 0.4f;
        /// <summary>Risk of Rain 2 monsters are tougher, smarter and much heavier to run than Megabonk's, so the target is this share of Megabonk's (about 30 alive at 4 minutes, the horde_limit cap by 10), never above horde_limit. (x)</summary>
        public static float HordeDensity = 0.35f;
        /// <summary>While fewer monsters are alive than the target, each monster director without a boss squad earns this much extra credit per missing monster per second (a Lemurian costs 11, a Beetle 8), so the horde fills up like Megabonk's. (credits per missing monster per s)</summary>
        public static float HordeFillCredit = 3.0f;
    }
}
